      segment:clean(getField(row,'SEGMENT')), segmentN:normalizeSearchText(getField(row,'SEGMENT')),
      vehicle:clean(getField(row,'VEHICLE')), vehicleN:normalizeSearchText(getField(row,'VEHICLE')),
