let filterInputTimer=0;
function scheduleFilterApply(action,delay=120){
  clearTimeout(filterInputTimer);
  filterInputTimer=setTimeout(()=>{
    filterInputTimer=0;
    (action||applyFilters)();
  },delay);
}
function flushPendingFilterApply(){
  if(filterInputTimer){
    clearTimeout(filterInputTimer);
    filterInputTimer=0;
  }
}

